test "ImmutableBoolPriorityQueue: fromMutable independence" {
    var m = BoolPriorityQueue.init(std.testing.allocator);
    defer m.deinit();
    m.push(true);
    m.push(false);
    var im = ImmutableBoolPriorityQueue.fromMutable(std.testing.allocator, &m);
    defer im.deinit();
    var m2 = im.toMutable();
    defer m2.deinit();
    m2.push(true);
    try std.testing.expectEqual(@as(usize, 2), im.len());
    try std.testing.expectEqual(@as(usize, 3), m2.len());
}
